mapper.update:
UPDATE `${table}`


        `${k}` = #{v}

    , updated_by = #{operator}, updated_at = NOW()

WHERE id = #{id}

UPDATE `${table}`
SET is_deleted = 1, updated_by = #{operator}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT MAX(version_no)
FROM cms_content_version
WHERE ref_table = #{refTable} AND ref_id = #{refId}

SELECT v.version_id, v.ref_table, v.ref_id, v.version_no, v.op_type, v.op_note, v.operator, DATE_FORMAT(v.operated_at, '%Y-%m-%dT%H:%i:%s') AS operated_at, c.config_key FROM cms_content_version v LEFT JOIN cms_site_config c ON v.ref_table = 'cms_site_config' AND v.ref_id = c.id WHERE v.ref_table IN
#{t}
ORDER BY v.version_id DESC LIMIT #{limit}

SELECT COUNT(*)
FROM cms_audit_log
WHERE action IN ('approve', 'rollback')
  AND ref_table = #{refTable}
  AND ref_title = #{refTitle}
